<script>window.tests=<?php echo json_encode($services); ?>;window.testSlots=<?php echo json_encode($slotMap); ?>;window.testBooked=<?php echo json_encode($booked); ?>;</script>
<script>
const tests=window.tests||[], slots=window.testSlots||{}, booked=window.testBooked||{};let selected=null;const date=document.getElementById('testDate'),time=document.getElementById('testTime'),timeline=document.getElementById('testTimeline');date.min=new Date().toISOString().slice(0,10);date.value=date.min;
function loadTest(id){selected=tests.find(x=>x.id===id);if(!selected)return;document.getElementById('selectedTest').textContent=selected.name;document.getElementById('selectedTestInfo').textContent=selected.description+' • '+selected.duration;document.getElementById('tProviderId').value=selected.id;document.getElementById('tProviderName').value=selected.name;document.getElementById('tServiceName').value=selected.name;document.getElementById('tCategory').value=selected.category;document.querySelector('.test-booking-panel').scrollIntoView({behavior:'smooth'});render();}
function render(){time.innerHTML='<option value="">Choose an available time</option>';timeline.innerHTML='';if(!selected){time.disabled=true;return}time.disabled=false;(slots[selected.id]||[]).forEach(s=>{const key=selected.id+'|'+date.value+'|'+s.slot_time,isBooked=!!booked[key],available=s.slot_status==='Available';const b=document.createElement('button');b.type='button';b.className='test-time '+(available&&!isBooked?'open':'closed');b.disabled=!available||isBooked;b.innerHTML='<strong>'+s.slot_time+'</strong><span>'+ (isBooked?'Booked':available?'Available':'Unavailable')+'</span>';b.onclick=()=>{time.value=s.slot_time;document.querySelectorAll('.test-time').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')};timeline.appendChild(b);if(available&&!isBooked){const o=document.createElement('option');o.value=s.slot_time;o.textContent=s.slot_time+' — Available';time.appendChild(o);}})}
date.addEventListener('change',render);document.querySelectorAll('.test-category-card').forEach(b=>b.onclick=()=>{document.querySelectorAll('.test-category-card').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');const c=b.dataset.category;document.getElementById('testTitle').textContent=c;document.getElementById('testSub').textContent=tests.filter(x=>x.category===c).length+' tests available in this category.';document.querySelectorAll('.test-card').forEach(x=>x.style.display=x.dataset.category===c?'flex':'none');document.querySelector('.test-list-section').scrollIntoView({behavior:'smooth'});});document.querySelectorAll('.test-book-btn').forEach(b=>b.onclick=()=>loadTest(b.dataset.id));
</script></body></html>
